	@Test
	void concurrentOpeningsOfOneCompiledFilterTemplateKeepIndependentTerminalAggregates() throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			var executor = Executors.newVirtualThreadPerTaskExecutor();
			TrackingFilter semantic = new TrackingFilter();
			RecordingNativeBooleanFilter template = fixture.recording(semantic);
			CountDownLatch ready = new CountDownLatch(2);
			CountDownLatch start = new CountDownLatch(1);
			Runnable run = () -> {
				ready.countDown();
				try {
					if (!start.await(30, TimeUnit.SECONDS)) {
						throw new AssertionError("native filter start gate timed out");
					}
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(failure);
				}
				fixture.block(row -> {
					NativeFilterLease selected = new NativeFilterLease();
					drainValues(row, selected.borrow(template), 8, false);
					selected.commit();
				});
			};
			var first = executor.submit(run);
			var second = executor.submit(run);
			try {
				assertThat(ready.await(30, TimeUnit.SECONDS)).as("both native filter openings reached their start gate")
						.isTrue();
				start.countDown();
				first.get(60, TimeUnit.SECONDS);
				second.get(60, TimeUnit.SECONDS);
			} finally {
				start.countDown();
				first.cancel(true);
				second.cancel(true);
				executor.shutdownNow();
				assertThat(executor.awaitTermination(60, TimeUnit.SECONDS))
						.as("native filter opening workers terminate before fixture close")
						.isTrue();
			}
			assertThat(fixture.statistics.typed).hasSize(2).allSatisfy(observation -> {
				assertThat(observation.completed()).isTrue();
				assertThat(observation.poisonReason()).isEmpty();
				assertThat(observation.passedCount()).isEqualTo(8L);
				assertThat(observation.filteredCount()).isZero();
			});
			assertThat(semantic.accepts).hasValue(16);
			assertThat(fixture.statistics.rawCalls).hasValue(0);
		}
	}

