	enum WeightedOwner {
		ROW,
		BATCH,
		GROUPED
	}

	@ParameterizedTest
	@EnumSource(WeightedOwner.class)
	void nonUnitPhysicalInvocationsCannotCertifyLogicalRowRatios(WeightedOwner owner) throws Exception {
		assertWeightedOwner(owner, 3L, false);
	}

	@ParameterizedTest
	@EnumSource(WeightedOwner.class)
	void unitWeightOwnersRetainTheirRealInputCompletion(WeightedOwner owner) throws Exception {
		assertWeightedOwner(owner, 1L, true);
	}

	private void assertWeightedOwner(WeightedOwner owner, long weight, boolean complete) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			TrackingFilter semantic = new TrackingFilter();
			RecordingNativeBooleanFilter template = fixture.recording(semantic);
			fixture.block(row -> {
				NativeFilterLease selected = new NativeFilterLease();
				NativeBooleanFilter filter = selected.borrow(template);
				long logicalRows = 0L;
				if (owner == WeightedOwner.BATCH) {
					WeightedBatchCursor input = new WeightedBatchCursor() {
						boolean emitted;

						@Override
						public int fill(NativeBatch batch) {
							if (emitted) {
								batch.clear();
								return 0;
							}
							emitted = true;
							batch.finishRows(4);
							return 4;
						}

						@Override
						public long weight(int physicalRow) {
							return weight;
						}

						@Override
						public void close() {
							emitted = true;
						}
					};
					NativeBatch batch = new NativeBatch(0, 4);
					try (var filtered = new FilterBatchCursor(input, filter, row)) {
						while (filtered.fill(batch) != 0) {
							for (int i = 0; i < batch.selectedCount; i++) {
								logicalRows += filtered.weight(batch.selection[i]);
							}
						}
					}
				} else {
					FactorizedRowCursor input = new FactorizedRowCursor() {
						int emitted;

						@Override
						public boolean next() {
							return emitted++ < 4;
						}

						@Override
						public long multiplicity() {
							return weight;
						}

						@Override
						public void close() {
							emitted = 4;
						}
					};
					if (owner == WeightedOwner.GROUPED) {
						try (var filtered = LmdbNativeFactorRows.restrict(
								LmdbNativeFactorRows.scalar(input, 0), filter, row, 0L)) {
							while (filtered.next()) {
								logicalRows += filtered.multiplicity();
							}
						}
					} else {
						try (var filtered = new FilterCursor(input, filter, row)) {
							while (filtered.next()) {
								logicalRows += filtered.multiplicity();
							}
						}
					}
				}
				assertThat(logicalRows).isEqualTo(4L * weight);
				selected.commit();
			});
			assertThat(semantic.accepts).hasValue(4);
			if (complete) {
				assertComplete(fixture.statistics, 4L, 0L);
			} else {
				assertIncomplete(fixture.statistics);
			}
		}
	}

