	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void anUnsubmittedTasksPrimarySuppressionIsVisibleBeforeConsumerCompletion(boolean error) throws Exception {
		var tasks = new NativeExecutionContext.WorkerTasks(1);
		Throwable primary = error ? new AssertionError("submission primary")
				: new IllegalStateException("submission primary");
		Throwable cleanup = new IllegalArgumentException("deferred startup cleanup");
		AtomicReference<Throwable> settlementFailure = new AtomicReference<>();
		AtomicReference<Throwable[]> observed = new AtomicReference<>();
		CountDownLatch notificationEntered = new CountDownLatch(1);
		CountDownLatch releaseNotification = new CountDownLatch(1);
		CountDownLatch returned = new CountDownLatch(1);
		tasks.afterSettlement(() -> {
			notificationEntered.countDown();
			awaitNativeTestGate(releaseNotification);
			raise(cleanup);
		});
		Thread waiter = Thread.ofVirtual().start(() -> {
			try {
				tasks.await();
				observed.set(primary.getSuppressed());
			} catch (InterruptedException problem) {
				Thread.currentThread().interrupt();
				settlementFailure.set(problem);
			} finally {
				returned.countDown();
			}
		});
		Thread settler = Thread.ofVirtual().start(() -> {
			try {
				tasks.countDown(primary);
			} catch (Throwable problem) {
				settlementFailure.set(problem);
			}
		});
		try {
			assertThat(notificationEntered.await(30, TimeUnit.SECONDS)).isTrue();
			assertThat(tasks.getCount()).isEqualTo(1L);
			assertThat(tasks.await(0L, TimeUnit.NANOSECONDS)).isFalse();
			awaitNativeThreadState(waiter, Thread.State.WAITING, returned);
			releaseNotification.countDown();
			assertThat(returned.await(30, TimeUnit.SECONDS)).isTrue();
			joinNativeTestThread(waiter);
			joinNativeTestThread(settler);
			assertThat(observed.get()).containsExactly(cleanup);
			assertThat(tasks.cleanupFailure()).isSameAs(cleanup);
			assertThat(settlementFailure.get()).isNull();
			assertThat(tasks.getCount()).isZero();
		} finally {
			releaseNotification.countDown();
			for (Thread thread : new Thread[] { settler, waiter }) {
				if (thread.isAlive()) {
					thread.interrupt();
					joinNativeTestThread(thread);
				}
			}
		}
	}

	private static void awaitNativeThreadState(Thread thread, Thread.State state, CountDownLatch returned) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
		while (thread.isAlive() && returned.getCount() != 0L && thread.getState() != state
				&& System.nanoTime() - deadline < 0L) {
			Thread.onSpinWait();
		}
		assertThat(thread.getState()).as("the actual API must block at its owned lifecycle fence").isEqualTo(state);
	}

	private static void joinNativeTestThread(Thread thread) throws InterruptedException {
		if (thread == null) {
			return;
		}
		thread.join(30_000L);
		assertThat(thread.isAlive()).as("bounded native lifecycle thread exit").isFalse();
	}

	/** A single carrier close must suffice even when its final lease belongs to captured worker cleanup. */
	@ParameterizedTest
	@CsvSource({ "false,0", "false,1", "false,2", "true,0", "true,1", "true,2" })
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void lastCapturedWorkerLeaseFinishesPendingRootAndChildCloses(boolean childOwner, int failureKind)
			throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			AtomicReference<NativeExecutionContext> root = new AtomicReference<>();
			AtomicReference<NativeExecutionContext> owner = new AtomicReference<>();
			AtomicReference<NativeExecutionContext.WorkerTasks> group = new AtomicReference<>();
			AtomicReference<Future<?>> task = new AtomicReference<>();
			AtomicReference<Throwable> reported = new AtomicReference<>();
			AtomicInteger reports = new AtomicInteger();
			AtomicInteger nativeCleanup = new AtomicInteger();
			AtomicInteger rootCleanup = new AtomicInteger();
			AtomicInteger childCleanup = new AtomicInteger();
			AtomicBoolean scopeTailClosed = new AtomicBoolean();
			CountDownLatch activated = new CountDownLatch(1);
			CountDownLatch releaseBody = new CountDownLatch(1);
			CountDownLatch leaseReleased = new CountDownLatch(1);
			CountDownLatch releaseScopeTail = new CountDownLatch(1);
			Throwable late = failureKind == 1 ? new IllegalStateException("captured worker scope cleanup")
					: failureKind == 2 ? new AssertionError("captured worker scope cleanup") : null;
			var executor = Executors.newVirtualThreadPerTaskExecutor();
			try {
				fixture.block(row -> {
					NativeExecutionContext context = row.evaluationScope().executionContext();
					root.set(context);
					NativeExecutionContext workerOwner = childOwner ? new NativeExecutionContext(context) : context;
					owner.set(workerOwner);
					NativeExecutionContext.Lease rootLease = context.retainLease();
					NativeExecutionContext.Lease childLease = childOwner ? workerOwner.retainLease() : null;
					NativeExecutionContext.WorkerTasks tasks = new NativeExecutionContext.WorkerTasks(1);
					group.set(tasks);
					workerOwner.registerFilterWorkers(tasks);
					context.nativeState(new Object(), () -> (AutoCloseable) () -> {
						assertThat(scopeTailClosed)
								.as("all captured-scope cleanup precedes context resources")
								.isTrue();
						assertThat(tasks.await(30, TimeUnit.SECONDS))
								.as("context cleanup must not await its own settlement")
								.isTrue();
						rootCleanup.incrementAndGet();
					});
					if (childOwner) {
						workerOwner.nativeState(new Object(), () -> (AutoCloseable) () -> {
							assertThat(scopeTailClosed).isTrue();
							childCleanup.incrementAndGet();
						});
					}
					NativeFilterLease selected = new NativeFilterLease();
					drainValues(row, selected.borrow(fixture.recording(new TrackingFilter())), 8, false);
					selected.commit();
					try (var registration = QueryExecutionContext.activateReplaySafepoint(() -> {
					}, () -> () -> () -> {
						try {
							if (childLease != null) {
								childLease.exhausted();
								childLease.close();
							}
							rootLease.exhausted();
							rootLease.close();
							leaseReleased.countDown();
							awaitNativeTestGate(releaseScopeTail);
							if (late != null) {
								raise(late);
							}
						} finally {
							scopeTailClosed.set(true);
						}
					})) {
						var captured = NativeExecutionContext.captureWorkerContext();
						task.set(executor.submit(() -> {
							try (var worker = tasks.enter(nativeCleanup::incrementAndGet, problem -> {
								reported.set(problem);
								reports.incrementAndGet();
							})) {
								worker.activate(captured);
								activated.countDown();
								awaitNativeTestGate(releaseBody);
							}
						}));
						assertThat(activated.await(30, TimeUnit.SECONDS)).isTrue();
					}
					if (childOwner) {
						workerOwner.close();
					}
				});
				// fixture.block's actual carrier has now reached EOF and closed exactly once. No retry by the
				// result caller is used below: settlement itself must finish both pending contexts.
				assertThat(root.get().isClosed()).isFalse();
				assertThat(rootCleanup).hasValue(0);
				assertThat(fixture.statistics.typed).isEmpty();
				releaseBody.countDown();
				assertThat(leaseReleased.await(30, TimeUnit.SECONDS)).isTrue();
				assertThat(root.get().isClosed()).as("releasing the final lease is not captured-scope EOF").isFalse();
				assertThat(rootCleanup).hasValue(0);
				assertThat(childCleanup).hasValue(0);
				assertThat(fixture.statistics.typed).isEmpty();
				releaseScopeTail.countDown();
				if (late == null) {
					task.get().get(60, TimeUnit.SECONDS);
				} else {
					assertThatThrownBy(() -> task.get().get(60, TimeUnit.SECONDS)).hasCause(late);
				}
				assertThat(group.get().await(30, TimeUnit.SECONDS)).isTrue();
				assertThat(nativeCleanup).hasValue(1);
				assertThat(root.get().isClosed()).isTrue();
				assertThat(owner.get().isClosed()).isTrue();
				assertThat(rootCleanup).hasValue(1);
				assertThat(childCleanup).hasValue(childOwner ? 1 : 0);
				if (late == null) {
					assertThat(reported.get()).isNull();
					assertThat(reports).hasValue(0);
					assertComplete(fixture.statistics, 8L, 0L);
				} else {
					assertThat(reported.get()).isSameAs(late);
					assertThat(reports).hasValue(1);
					assertIncomplete(fixture.statistics);
				}
				root.get().close();
				owner.get().close();
				assertThat(rootCleanup).hasValue(1);
				assertThat(childCleanup).hasValue(childOwner ? 1 : 0);
				assertThat(fixture.statistics.typed).hasSize(1);
			} finally {
				releaseBody.countDown();
				releaseScopeTail.countDown();
				Future<?> submitted = task.get();
				if (submitted != null) {
					submitted.cancel(true);
				}
				executor.shutdownNow();
				assertThat(executor.awaitTermination(60, TimeUnit.SECONDS)).isTrue();
			}
		}
	}

