	@ParameterizedTest
	@CsvSource({ "true,-1,128", "false,-1,128", "true,0,128", "false,0,128",
			"true,3,128", "false,3,128", "true,-1,0", "false,-1,0" })
	void actualGeneratedAndInterpretedKernelsDistinguishInputEofFromOutputCutoff(
			boolean generated, long limit, int inputCount) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			fixture.block(parent -> {
				NativeSlotLayout layout = new NativeSlotLayout(Map.of("v", 0), null);
				layout.freeze(List.of("v"));
				RowState row = new RowState(parent.source, layout, EmptyBindingSet.getInstance());
				NativeBooleanFilter semantic = value -> ((Literal) value.source.lazyValue(value.slots[0])).intValue()
						% 4 == 0;
				NativeFilterLease selected = new NativeFilterLease();
				NativeBooleanFilter filter = selected.borrow(fixture.recording(semantic));
				long[] domain = new long[inputCount];
				for (int i = 0; i < domain.length; i++) {
					domain[i] = row.source.idOf(fixture.repository.getValueFactory().createLiteral(i));
					assertThat(domain[i]).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				}
				var ir = new LmdbNativeKernelIr.Kernel(1, List.of(new LmdbNativeKernelIr.EnumerateDomain(0, 0),
						new LmdbNativeKernelIr.FilterValue(0,
								new LmdbNativeKernelIr.Operand[] { LmdbNativeKernelIr.Operand.col(0) })),
						new LmdbNativeKernelIr.Emit(new int[] { 0 }, false,
								new LmdbNativeKernelIr.OutputMods(null, null, false, limit, 0L)));
				JaninoKernel kernel = generated ? KernelCompilationTestSupport.compile(ir)
						: LmdbNativeKernelInterpreter.forRows(ir);
				assertThat(kernel).isNotNull();
				var bindings = new LmdbNativeKernelBindings(new LmdbNativeKernelBindings.AdjacencyRequest[0],
						new long[0],
						new int[0], new LmdbNativeKernelBindings.DomainRequest[0],
						new LmdbNativeKernelBindings.FilterHook[] { new LmdbNativeKernelBindings.FilterHook(
								new MaskedFilter(filter, 1L), new int[] { 0 }) },
						new int[] { 0 }, List.of());
				LmdbNativeKernelHooks hooks = new LmdbNativeKernelHooks(row, bindings);
				List<Integer> output = new ArrayList<>();
				Throwable primary = null;
				try {
					kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], new long[0],
							new long[0], new long[][] { domain }, hooks));
					long[] buffer = new long[32];
					int filled = kernel.fill(buffer, 32);
					if (inputCount == 128 && limit < 0) {
						assertThat(kernel.filterInputExhausted()).as("a full output page is not EOF").isFalse();
					}
					while (filled > 0) {
						for (int i = 0; i < filled; i++) {
							output.add(((Literal) row.source.lazyValue(buffer[i])).intValue());
						}
						filled = kernel.fill(buffer, 32);
					}
					assertThat(kernel.filterInputExhausted()).isEqualTo(limit < 0);
				} catch (RuntimeException | Error failure) {
					primary = failure;
					throw failure;
				} finally {
					closeKernelAndHooks(kernel, hooks, primary);
				}
				selected.commit();
				if (limit < 0 && inputCount > 0) {
					assertQuarterBag(output);
				} else {
					assertThat(output).hasSize(inputCount == 0 || limit == 0 ? 0 : 3);
				}
			});
			if (limit < 0) {
				assertComplete(fixture.statistics, inputCount == 0 ? 0 : 32, inputCount == 0 ? 0 : 96);
			} else {
				assertIncomplete(fixture.statistics);
			}
		}
	}

