	private static void closeKernelAndHooks(JaninoKernel kernel, LmdbNativeKernelHooks hooks, Throwable primary) {
		Throwable failure = primary;
		boolean complete = primary == null && kernel.filterInputExhausted();
		try {
			kernel.close();
		} catch (RuntimeException | Error problem) {
			if (failure == null) {
				failure = problem;
			} else if (failure != problem) {
				failure.addSuppressed(problem);
			}
		}
		try {
			hooks.closeFilters(complete && failure == null);
		} catch (RuntimeException | Error problem) {
			if (failure == null) {
				failure = problem;
			} else if (failure != problem) {
				failure.addSuppressed(problem);
			}
		}
		if (primary == null && failure != null) {
			raise(failure);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nativeLexicalBoundaryFailureClosesItsInputWithoutPublishingMemo(boolean bodyFails) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			AtomicInteger opens = new AtomicInteger();
			AtomicInteger closes = new AtomicInteger();
			RuntimeException body = new IllegalStateException("native lexical body failure");
			RuntimeException cleanup = new IllegalArgumentException("native lexical input close failure");
			RuntimeException primary = bodyFails ? body : cleanup;
			fixture.block(row -> {
				QueryEvaluationStep step = input -> {
					opens.incrementAndGet();
					return new CloseableIteration<BindingSet>() {
						@Override
						public boolean hasNext() {
							if (bodyFails) {
								throw body;
							}
							return false;
						}

						@Override
						public BindingSet next() {
							throw new NoSuchElementException();
						}

						@Override
						public void close() {
							closes.incrementAndGet();
							throw cleanup;
						}
					};
				};
				// This existing constructor grants no movement proof. The real row owns the lexical memo and capture.
				NativeSubqueryPlan boundary = new NativeSubqueryPlan(step, new int[0], new String[0], new int[0],
						new String[0]);
				assertThatThrownBy(() -> drainPlan(boundary, row)).isSameAs(primary);
				assertThat(opens).hasValue(1);
				assertThat(closes).hasValue(1);
				if (bodyFails) {
					assertThat(primary.getSuppressed()).containsExactly(cleanup);
				}
				assertThat(row.evaluationScope().executionContext().isClosed()).isFalse();
				// No failed partial materialization is published as an empty successful memo.
				assertThatThrownBy(() -> drainPlan(boundary, row)).isSameAs(primary);
				assertThat(opens).hasValue(2);
				assertThat(closes).hasValue(2);
			});
			assertThat(fixture.statistics.typed).isEmpty();
		}
	}

	private static int drainPlan(SlotPlan plan, RowState row) throws IOException {
		int count = 0;
		try (RowCursor cursor = plan.open(row)) {
			while (cursor.next()) {
				count++;
			}
		}
		return count;
	}

	private static <T> LmdbNativeDispatchLoop.Selection<T> select(LmdbNativeDecisionPoint point,
			LmdbNativeOffers<T> offers, RowState row, NativeFilterLease parent) throws IOException {
		return new LmdbNativeDispatchLoop<>(point, offers.strategies(), null)
				.sharedRow(row)
				.filterParent(parent == null ? NativeFilterLease.parentOf(row) : parent)
				.dispatch(null);
	}

	private static <T> void consumeSelected(LmdbNativeDispatchLoop.Selection<T> selected, Consumer<T> consume) {
		assertThat(selected).as("the production selector must open a candidate").isNotNull();
		Throwable primary = null;
		try {
			consume.accept(selected.value());
		} catch (RuntimeException | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			Throwable retained = selected.finish(primary);
			KernelRuntime.rethrowCloseFailureIfNotPrimary(retained, primary);
		}
	}

